const SC=document.getElementById("scatterCanvas");
const sdpr=Math.min(window.devicePixelRatio||1,2);
const SW=620,SH=420;SC.width=SW*sdpr;SC.height=SH*sdpr;SC.style.width=SW+"px";SC.style.height=SH+"px";
const sctx=SC.getContext("2d");sctx.scale(sdpr,sdpr);
const COUNTRIES=[{n:"South Africa",x:3,y:72.2,c:"var(--greenl)",note:"TCCs · No DP"},{n:"UK",x:4.5,y:53.4,c:"var(--gold)",note:"CPS 2024"},{n:"India",x:6,y:27.4,c:"var(--amber)",note:"NCRB 2022"},{n:"Nepal",x:7,y:5,c:"rgba(122,200,160,.8)",note:"Limited data"},{n:"Indonesia",x:8.5,y:2,c:"rgba(180,120,80,.8)",note:"Post-DP surge"},{n:"Bangladesh",x:10,y:.46,c:"#e84060",note:"DP 2020",hi:true}];
const SP={t:40,r:150,b:60,l:70};const SCW2=SW-SP.l-SP.r,SCH2=SH-SP.t-SP.b;
let scStep=-1;
function drawScatter(step){
  sctx.clearRect(0,0,SW,SH);
  const SPLIT=0.58;
  function yp(v){if(v>=10){return SP.t+SCH2*SPLIT*(1-(v-10)/70);}else{const breakY=SP.t+SCH2*SPLIT;return breakY+28+(SCH2*(1-SPLIT)-28)*(1-v/10);}}
  const xp=x=>SP.l+(x/11)*SCW2;
  sctx.strokeStyle="rgba(180,175,180,.65)";sctx.lineWidth=1;
  [80,60,40,20,10].forEach(v=>{const y=yp(v);sctx.beginPath();sctx.moveTo(SP.l,y);sctx.lineTo(SP.l+SCW2,y);sctx.stroke();sctx.fillStyle="rgba(90,88,105,.9)";sctx.font="10px IBM Plex Mono,monospace";sctx.textAlign="right";sctx.fillText(v+"%",SP.l-8,y+4);});
  const bY=SP.t+SCH2*SPLIT;
  sctx.fillStyle="rgba(238,236,231,1)";sctx.fillRect(SP.l-4,bY+2,SCW2+8,24);
  sctx.strokeStyle="rgba(78,75,96,.4)";sctx.lineWidth=1;sctx.setLineDash([4,3]);
  sctx.beginPath();sctx.moveTo(SP.l,bY+2);sctx.lineTo(SP.l+SCW2,bY+2);sctx.stroke();
  sctx.beginPath();sctx.moveTo(SP.l,bY+26);sctx.lineTo(SP.l+SCW2,bY+26);sctx.stroke();
  sctx.setLineDash([]);
  sctx.strokeStyle="rgba(122,117,144,.7)";sctx.lineWidth=1.5;
  const bx=SP.l-6;sctx.beginPath();sctx.moveTo(bx,bY+4);sctx.lineTo(bx+4,bY+10);sctx.lineTo(bx-2,bY+16);sctx.lineTo(bx+4,bY+22);sctx.stroke();
  [0,5].forEach(v=>{const y=yp(v);sctx.strokeStyle="rgba(180,175,180,.65)";sctx.lineWidth=1;sctx.beginPath();sctx.moveTo(SP.l,y);sctx.lineTo(SP.l+SCW2,y);sctx.stroke();sctx.fillStyle="rgba(90,88,105,.9)";sctx.font="10px IBM Plex Mono,monospace";sctx.textAlign="right";sctx.fillText(v+"%",SP.l-8,y+4);});
  sctx.strokeStyle="rgba(180,175,180,.45)";[2,4,6,8,10].forEach(x=>{sctx.beginPath();sctx.moveTo(xp(x),SP.t);sctx.lineTo(xp(x),SP.t+SCH2);sctx.stroke();});
  sctx.fillStyle="rgba(90,88,105,.9)";sctx.font="10px IBM Plex Mono,monospace";sctx.textAlign="center";
  sctx.fillText("← LOWER SEVERITY",xp(2),SP.t+SCH2+38);sctx.fillText("HIGHER SEVERITY →",xp(9),SP.t+SCH2+38);
  sctx.save();sctx.translate(16,SP.t+SCH2/2);sctx.rotate(-Math.PI/2);sctx.textAlign="center";sctx.fillText("CONVICTION RATE →",0,0);sctx.restore();
  if(step>=1){sctx.beginPath();sctx.strokeStyle="rgba(82,183,136,.15)";sctx.lineWidth=1.5;sctx.setLineDash([6,4]);sctx.moveTo(xp(2),yp(72));sctx.lineTo(xp(11),yp(8));sctx.stroke();sctx.setLineDash([]);}
  const vis=step===0?2:step===1?4:COUNTRIES.length;
  COUNTRIES.slice(0,vis).forEach(c=>{
    const px=xp(c.x),py=yp(c.y);const r=c.hi?11:7;
    sctx.beginPath();sctx.arc(px,py,r,0,Math.PI*2);sctx.fillStyle=c.c;sctx.fill();
    if(c.hi){sctx.strokeStyle="rgba(232,64,96,.6)";sctx.lineWidth=2;sctx.stroke();}
    let lx=px+r+6,ly=py-6,ta="left";
    if(c.n==="Bangladesh"){lx=px-r-8;ly=py-14;ta="right";}
    else if(c.n==="Indonesia"){lx=px-r-8;ly=py+6;ta="right";}
    else if(c.n==="Nepal"){lx=px+r+6;ly=py-14;ta="left";}
    sctx.fillStyle=c.c;sctx.font=(c.hi?"bold 11px":"10px")+" IBM Plex Mono,monospace";sctx.textAlign=ta;sctx.fillText(c.n,lx,ly);
    sctx.fillStyle="rgba(100,98,112,.82)";sctx.font="9px IBM Plex Mono,monospace";sctx.fillText(c.y+"% · "+c.note,lx,ly+13);
  });
  if(step>=2&&vis>=COUNTRIES.length){
    const bd=COUNTRIES[5];const px=xp(bd.x),py=yp(bd.y);
    sctx.strokeStyle="rgba(232,64,96,.35)";sctx.lineWidth=1;sctx.setLineDash([3,3]);
    sctx.beginPath();sctx.moveTo(px,py+12);sctx.lineTo(px,SP.t+SCH2);sctx.stroke();
    sctx.beginPath();sctx.moveTo(SP.l,py);sctx.lineTo(px-12,py);sctx.stroke();sctx.setLineDash([]);
    const cx=xp(7.5),cy=yp(3.5);
    sctx.fillStyle="rgba(196,30,58,.12)";sctx.fillRect(cx-55,cy-14,180,40);
    sctx.strokeStyle="rgba(232,64,96,.4)";sctx.lineWidth=1;sctx.strokeRect(cx-55,cy-14,180,40);
    sctx.fillStyle="rgba(232,64,96,.9)";sctx.font="bold 10px IBM Plex Mono,monospace";sctx.textAlign="left";sctx.fillText("← WORST CORNER",cx-50,cy+2);
    sctx.fillStyle="rgba(100,98,112,.78)";sctx.font="9px IBM Plex Mono,monospace";sctx.fillText("Max severity + Near-zero certainty",cx-50,cy+16);
  }
}
drawScatter(0);

